CREATE TABLE egresos(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,fecha DATE NOT NULL,concepto VARCHAR(150) NOT NULL,descripcion VARCHAR(500),monto NUMERIC(12,2) NOT NULL CHECK(monto>0),metodo VARCHAR(30) NOT NULL,comprobante VARCHAR(60) NOT NULL UNIQUE,estado VARCHAR(20) NOT NULL DEFAULT 'REGISTRADO',motivo_anulacion VARCHAR(500),usuario_id BIGINT NOT NULL REFERENCES usuarios(id),fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE devoluciones(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,pago_id BIGINT NOT NULL REFERENCES pagos(id),monto NUMERIC(12,2) NOT NULL CHECK(monto>0),motivo VARCHAR(500) NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'SOLICITADA',fecha DATE NOT NULL,usuario_id BIGINT NOT NULL REFERENCES usuarios(id),fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_egresos_fecha_estado ON egresos(fecha,estado);
CREATE INDEX idx_devoluciones_pago_estado ON devoluciones(pago_id,estado);
